import{_ as e,o,c as d,a3 as r}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"AI Purchase Order triage tools (ai 1.10.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Purchase Order triage tools (ai 1.10.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/ai-purchase-order-triage-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Purchase Order triage tools (ai 1.10.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/ai-purchase-order-triage-production-readiness"}]]},"headers":[],"relativePath":"deployment/ai-purchase-order-triage-production-readiness.md","filePath":"deployment/ai-purchase-order-triage-production-readiness.md","lastUpdated":1790450426000}'),a={name:"deployment/ai-purchase-order-triage-production-readiness.md"};function s(n,t,i,c,l,g){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-purchase-order-triage-tools-ai-1-10-0-—-production-readiness-audit" tabindex="-1">AI Purchase Order triage tools (ai 1.10.0) — Production Readiness Audit <a class="header-anchor" href="#ai-purchase-order-triage-tools-ai-1-10-0-—-production-readiness-audit" aria-label="Permalink to &quot;AI Purchase Order triage tools (ai 1.10.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-15</td></tr><tr><td><strong>Re-audited</strong></td><td>2026-09-15</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Backend + Docs; <strong>no SPA/Mobile code</strong></td></tr><tr><td><strong>Scope</strong></td><td>Ask EloSync Purchase Order tools: <code>get_purchase_order</code> plus confirmed writes <code>update_purchase_order_status</code> / <code>assign_purchase_order</code> / <code>add_purchase_order_note</code>; get payload <code>assigned_to</code> (user id) + <code>assignee_name</code>; catalog <strong>ai 1.9.0 → 1.10.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./ai">AI deployment</a> · <a href="./ai-project-triage-production-readiness">AI Project triage</a> · <a href="./ai-payment-triage-production-readiness">AI Payment triage</a> · <a href="/developer-guide/ai-tools">AI tools</a> · <a href="/api/tenant-v1-ai">Tenant AI API</a> · <a href="/user-guide/ai-assistant">User guide</a> · <a href="/user-guide/purchase-orders-overview">Purchase Orders</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Additive AI tools depth on the existing <code>AIGateway</code> + <code>AIToolRegistry</code> + <code>PendingAiActionService</code> path. Reads: fetch one purchase order. Writes: three low-risk tools that propose pending actions; mutations run only after <code>POST /ai/actions/{id}/confirm</code>. Status changes call <code>PurchaseOrderService::changeStatus</code> (same as HTTP <code>POST …/status</code>). Status auth mirrors the controller: Sent→<code>send</code>, PartiallyReceived/Received→<code>receive</code>, Cancelled→<code>cancel</code>, else→<code>update</code>. Registry visibility for status uses <code>AiToolAnyOfPermissions</code> (<code>purchase-orders.update</code> | <code>send</code> | <code>receive</code> | <code>cancel</code>). Assign uses <code>purchase-orders.assign</code> + <code>EligiblePurchaseOrderAssignee</code> at propose <strong>and</strong> confirm. Notes are text-only with confirm-time <code>max:5000</code>. No new Spatie permissions, no Purchase Orders catalog bump, no Frontend/Mobile changes.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>. Cutover: migrate-only catalog bump to <strong>1.10.0</strong>, entitle <code>ai</code> + <code>purchase-orders</code>, staging smoke propose→confirm.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel AI stack)</td><td><strong>Pass</strong></td></tr><tr><td>UUID PO lookup; soft-deleted excluded</td><td><strong>Pass</strong></td></tr><tr><td>Status propose/confirm: target-dependent send/receive/cancel/update + <code>changeStatus</code></td><td><strong>Pass</strong></td></tr><tr><td>Status tool visible with any of update/send/receive/cancel</td><td><strong>Pass</strong></td></tr><tr><td>Assign gated by <code>purchase-orders.assign</code> + eligible assignee (propose <strong>and</strong> confirm)</td><td><strong>Pass</strong></td></tr><tr><td>Note gated by <code>purchase-orders.update</code> + policy <code>update</code> + body max 5000 on confirm</td><td><strong>Pass</strong></td></tr><tr><td>Propose does not mutate</td><td><strong>Pass</strong></td></tr><tr><td>Get payload exposes <code>assigned_to</code> (id) + <code>assignee_name</code></td><td><strong>Pass</strong></td></tr><tr><td>Catalog migrate-only <code>ai</code> <strong>1.10.0</strong> + CatalogSeeder sync</td><td><strong>Pass</strong></td></tr><tr><td>Docs (tools, API, user tip, PO cross-links, ops, roadmap, changelog, upgrade, VitePress)</td><td><strong>Pass</strong></td></tr><tr><td>Pest write confirmation + registry</td><td><strong>Pass</strong></td></tr><tr><td>Playwright AI e2e</td><td><strong>N/A</strong> — no SPA surface change</td></tr></tbody></table><hr><h2 id="locked-decision-matrix" tabindex="-1">Locked-decision matrix <a class="header-anchor" href="#locked-decision-matrix" aria-label="Permalink to &quot;Locked-decision matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Backend</th><th>Frontend</th><th>Mobile</th><th>Docs</th></tr></thead><tbody><tr><td>Read tool <code>get_purchase_order</code></td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td>Confirmed writes via existing pending actions</td><td>Pass</td><td>Pass (generic UI)</td><td>Pass (generic UI)</td><td>Pass</td></tr><tr><td>Status via HTTP <code>/status</code> semantics</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td><code>AiToolAnyOfPermissions</code> for status visibility</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td>Catalog MINOR <strong>ai 1.10.0</strong> only (not purchase-orders)</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr></tbody></table><hr><h2 id="authz-map-http-↔-ai" tabindex="-1">Authz map (HTTP ↔ AI) <a class="header-anchor" href="#authz-map-http-↔-ai" aria-label="Permalink to &quot;Authz map (HTTP ↔ AI)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>HTTP</th><th>AI tool / confirm</th></tr></thead><tbody><tr><td>Get one</td><td><code>view</code></td><td><code>get_purchase_order</code></td></tr><tr><td>Change status</td><td>target-dependent (<code>send</code> / <code>receive</code> / <code>cancel</code> / <code>update</code>) + <code>POST …/status</code></td><td><code>update_purchase_order_status</code> → <code>PurchaseOrderAiSupport::authorizeStatusChange</code> + <code>changeStatus</code></td></tr><tr><td>Assign / unassign</td><td><code>assign</code></td><td><code>assign_purchase_order</code> + eligible assignee at propose <strong>and</strong> confirm</td></tr><tr><td>Note (text)</td><td><code>update</code></td><td><code>add_purchase_order_note</code> + confirm <code>max:5000</code></td></tr></tbody></table><hr><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade / staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade / staging smoke&quot;">​</a></h2><p>After migrate (<code>2026_09_15_100000_bump_ai_module_version_to_1_10_0</code>):</p><ol><li>Confirm central catalog <code>ai.version</code> = <strong>1.10.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Workspace has <strong>AI</strong> + <strong>Purchase Orders</strong> entitled; user has <code>ai.use</code>, <code>ai.confirm</code>, and PO domain perms as needed.</li><li>Ask EloSync: fetch PO → propose status/assign/note → Confirm.</li><li>Send-only can propose Draft→Sent; receive/cancel need matching perms; view-only never gets writes.</li></ol><p>See <a href="./upgrade#ai-purchase-order-triage-tools-190--1100">Upgrade Guide</a> · <a href="./ai">AI deployment</a>.</p><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Redeploy previous Backend release. Catalog version may remain <strong>1.10.0</strong> (display-only); tools disappear with the code rollback. Pending actions for removed tools fail confirm with unsupported tool — cancel or let expire (24h).</p>',21)])])}const p=e(a,[["render",s]]);export{h as __pageData,p as default};
